+
+fn render_table_key(key: &str) -> String {
+    if key
+        .chars()
+        .all(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '-')
+    {
+        key.to_string()
+    } else {
+        format!("\"{}\"", key.replace('\\', "\\\\").replace('"', "\\\""))
+    }
+}
+
+fn render_toml_string(value: &str) -> String {
+    if value.is_empty() {
+        return "''".to_string();
+    }
+
+    if !value.contains('\n') && !value.contains('\'') && !has_disallowed_literal_chars(value) {
+        return format!("'{}'", value);
+    }
+
+    if !value.contains("'''") && !has_disallowed_literal_chars(value) {
+        let mut out = String::from("'''");
+        out.push('\n');
+        out.push_str(value);
+        out.push_str("'''");
+        return out;
+    }
+
+    format!("\"{}\"", escape_basic_toml(value))
+}
+
+fn has_disallowed_literal_chars(value: &str) -> bool {
+    value.chars().any(|ch| matches!(ch, '\u{0000}'..='\u{0008}' | '\u{000A}'..='\u{001F}' | '\u{007F}'))
+}
+
+fn escape_basic_toml(value: &str) -> String {
+    let mut out = String::new();
+    for ch in value.chars() {
+        match ch {
+            '\\' => out.push_str("\\\\"),
+            '"' => out.push_str("\\\""),
+            '\u{08}' => out.push_str("\\b"),
+            '\t' => out.push_str("\\t"),
+            '\n' => out.push_str("\\n"),
+            '\u{0C}' => out.push_str("\\f"),
+            '\r' => out.push_str("\\r"),
+            ch if ch.is_control() => out.push_str(&format!("\\u{:04X}", ch as u32)),
+            _ => out.push(ch),
+        }
+    }
+    out
+}
+
+fn default_init_config() -> String {
+    "[scripts.hello-pier]\ncommand = 'echo Hello, Pier!'\ndescription = 'This is an example command.'\n\n[default]\n".to_string()
+}
+
+fn edit_with_editor(initial_contents: &str) -> Result<String, PierError> {
+    let editor = env::var("EDITOR").unwrap_or_else(|_| "vi".to_string());
+    let parts = split_shell_words(&editor).unwrap_or_else(|_| vec![editor.clone()]);
+    let Some(program) = parts.first() else {
+        return Err(PierError::Editor(editor));
+    };
+
+    let mut file = NamedTempFile::new().map_err(|_| PierError::Editor(editor.clone()))?;
+    file.write_all(initial_contents.as_bytes())
+        .map_err(|_| PierError::Editor(editor.clone()))?;
+    file.flush().map_err(|_| PierError::Editor(editor.clone()))?;
