+        out.push('\n');
+    }
+    out.push_str(&separator);
+    out.push('\n');
+    out
+}
+
+fn max_width<'a>(header: &str, values: impl Iterator<Item = &'a str>) -> usize {
+    values.fold(UnicodeWidthStr::width(header), |width, value| {
+        width.max(UnicodeWidthStr::width(value))
+    })
+}
+
+fn format_row(columns: &[&str], widths: &[usize; 4]) -> String {
+    let mut out = String::from("⋮");
+    for (index, column) in columns.iter().enumerate() {
+        out.push(' ');
+        out.push_str(column);
+        let padding = widths[index].saturating_sub(UnicodeWidthStr::width(*column));
+        out.push_str(&" ".repeat(padding));
+        out.push(' ');
+        out.push('⋮');
+    }
+    out
+}
