fn build_list_subcommand() -> App<'static, 'static> {
    SubCommand::with_name("list")
        .version(VERSION)
        .about("alias: ls - List scripts")
        .long_about("alias: ls - List scripts\n\nDisplay options are determined by priority in this order:\n\n1. List only aliases\n\n2. Show full command\n\n3. Command display with (cli option)\n\n4. Command display with (config option)")
        .alias("ls")
