fn dispatch(matches: &ArgMatches<'_>) -> Result<(), PierError> {
    match matches.subcommand() {
        ("add", Some(sub_matches)) => cmd_add(matches, sub_matches),
        ("config-init", Some(_)) => cmd_config_init(matches),
        ("copy", Some(sub_matches)) => cmd_copy(matches, sub_matches),
        ("edit", Some(sub_matches)) => cmd_edit(matches, sub_matches),
        ("list", Some(sub_matches)) => cmd_list(matches, sub_matches),
        ("move", Some(sub_matches)) => cmd_move(matches, sub_matches),
        ("remove", Some(sub_matches)) => cmd_remove(matches, sub_matches),
        ("run", Some(sub_matches)) => cmd_run(matches, sub_matches),
        ("show", Some(sub_matches)) => cmd_show(matches, sub_matches),
        _ => cmd_direct_run(matches),
    }
}

fn cmd_config_init(global_matches: &ArgMatches<'_>) -> Result<(), PierError> {
    let path = resolve_init_config_path(global_matches)?;
    if path.exists() {
        return Err(PierError::InitExists(path));
    }

    write_config_file(&path, default_init_config())?;
    println!("Added hello-pier");
    Ok(())
}

fn cmd_add(global_matches: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), PierError> {
    let path = resolve_existing_config_path(global_matches)?;
    let mut config = load_config(&path)?;

    let alias = matches.value_of("alias").unwrap();
    if config.scripts.contains_key(alias) && !matches.is_present("force") {
        return Err(PierError::AliasAlreadyExists(alias.to_string()));
    }

    let command = match matches.value_of("command") {
        Some(command) => command.to_string(),
        None => edit_with_editor("")?,
    };
    let description = matches.value_of("description").map(str::to_string);
    let tags = values_to_vec(matches, "tags");

    config.scripts.insert(
        alias.to_string(),
        Script {
            command,
            description,
            tags,
        },
    );
    write_config(&path, &config)?;
    println!("Added {alias}");
    Ok(())
}

fn cmd_edit(global_matches: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), PierError> {
    let path = resolve_existing_config_path(global_matches)?;
    let mut config = load_config(&path)?;
    ensure_scripts_exist(&config)?;

    let alias = matches.value_of("alias").unwrap();
    let script = config
        .scripts
        .get_mut(alias)
        .ok_or_else(|| PierError::AliasNotFound(alias.to_string()))?;

    script.command = edit_with_editor(&script.command)?;
    write_config(&path, &config)?;
    println!("Edited {alias}");
    Ok(())
}

fn cmd_list(global_matches: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), PierError> {
    let path = resolve_existing_config_path(global_matches)?;
    let config = load_config(&path)?;
    ensure_scripts_exist(&config)?;

    let entries = filtered_entries(&config, matches);
    let cli_list_aliases = matches.is_present("list-aliases");
    let cli_cmd_full = matches.is_present("cmd-full");
    let cli_cmd_width = matches
        .value_of("cmd-width")
        .and_then(|value| value.parse::<usize>().ok());

    let list_aliases = cli_list_aliases || (!cli_list_aliases && !cli_cmd_full && cli_cmd_width.is_none() && config.default.list_aliases);
    if list_aliases {
        for (alias, _) in &entries {
            println!("{alias}");
        }
        return Ok(());
    }

    let command_display = if cli_cmd_full {
        CommandDisplay::Full
    } else if let Some(width) = cli_cmd_width {
        CommandDisplay::Width(width)
    } else if config.default.cmd_full {
        CommandDisplay::Full
    } else if let Some(width) = config.default.cmd_width {
        CommandDisplay::Width(width)
    } else {
        CommandDisplay::Full
    };

    print!("{}", render_table(&entries, command_display));
    Ok(())
}

fn cmd_remove(global_matches: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), PierError> {
    let path = resolve_existing_config_path(global_matches)?;
    let mut config = load_config(&path)?;
    ensure_scripts_exist(&config)?;

    let alias = matches.value_of("alias").unwrap();
    if config.scripts.remove(alias).is_none() {
        return Err(PierError::AliasNotFound(alias.to_string()));
    }

    write_config(&path, &config)?;
    println!("Removed {alias}");
    Ok(())
}

fn cmd_copy(global_matches: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), PierError> {
    let path = resolve_existing_config_path(global_matches)?;
    let mut config = load_config(&path)?;
    ensure_scripts_exist(&config)?;

    let from = matches.value_of("from-alias").unwrap();
    let to = matches.value_of("to-alias").unwrap();

    let script = config
        .scripts
        .get(from)
        .cloned()
        .ok_or_else(|| PierError::AliasNotFound(from.to_string()))?;
    if config.scripts.contains_key(to) {
        return Err(PierError::AliasAlreadyExists(to.to_string()));
    }

    config.scripts.insert(to.to_string(), script);
    write_config(&path, &config)?;
    println!("Copy from alias {from} to new alias {to}");
    Ok(())
}

fn cmd_move(global_matches: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), PierError> {
    let path = resolve_existing_config_path(global_matches)?;
    let mut config = load_config(&path)?;
    ensure_scripts_exist(&config)?;

    let from = matches.value_of("from-alias").unwrap();
    let to = matches.value_of("to-alias").unwrap();
    let force = matches.is_present("force");

    let script = config
        .scripts
        .get(from)
        .cloned()
        .ok_or_else(|| PierError::AliasNotFound(from.to_string()))?;
    if config.scripts.contains_key(to) && from != to && !force {
        return Err(PierError::AliasAlreadyExists(to.to_string()));
    }
    if config.scripts.contains_key(to) && from == to && !force {
        return Err(PierError::AliasAlreadyExists(to.to_string()));
    }

    config.scripts.remove(from);
    config.scripts.insert(to.to_string(), script);
    write_config(&path, &config)?;
    println!("Move from alias {from} to new alias {to}");
    Ok(())
}

fn cmd_show(global_matches: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), PierError> {
    let path = resolve_existing_config_path(global_matches)?;
    let config = load_config(&path)?;
    ensure_scripts_exist(&config)?;

    let alias = matches.value_of("alias").unwrap();
    let script = config
        .scripts
        .get(alias)
        .ok_or_else(|| PierError::AliasNotFound(alias.to_string()))?;
    println!("{}", script.command);
    Ok(())
}

fn cmd_run(global_matches: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), PierError> {
    let path = resolve_existing_config_path(global_matches)?;
    let config = load_config(&path)?;
    ensure_scripts_exist(&config)?;

    let alias = matches.value_of("alias").unwrap();
    let script = config
        .scripts
        .get(alias)
        .ok_or_else(|| PierError::AliasNotFound(alias.to_string()))?;
    let args = values_to_vec(matches, "args");
    let exit_code = run_script(alias, &script.command, &args)?;
    process::exit(exit_code);
}

fn cmd_direct_run(matches: &ArgMatches<'_>) -> Result<(), PierError> {
    let path = resolve_existing_config_path(matches)?;
    let config = load_config(&path)?;
    ensure_scripts_exist(&config)?;

    let alias = matches.value_of("alias").unwrap();
    let script = config
        .scripts
        .get(alias)
        .ok_or_else(|| PierError::AliasNotFound(alias.to_string()))?;
    let args = values_to_vec(matches, "args");
    let exit_code = run_script(alias, &script.command, &args)?;
    process::exit(exit_code);
}

fn ensure_scripts_exist(config: &Config) -> Result<(), PierError> {
    if config.scripts.is_empty() {
        Err(PierError::NoScripts)
    } else {
        Ok(())
    }
}

fn resolve_init_config_path(matches: &ArgMatches<'_>) -> Result<PathBuf, PierError> {
    if let Some(path) = matches.value_of("config-file") {
        return Ok(PathBuf::from(path));
    }

    if let Some(path) = find_default_config_path() {
        return Ok(path);
    }

    preferred_new_config_path().ok_or(PierError::NoDefaultConfig)
}

fn resolve_existing_config_path(matches: &ArgMatches<'_>) -> Result<PathBuf, PierError> {
    if let Some(path) = matches.value_of("config-file") {
        return Ok(PathBuf::from(path));
    }

    find_default_config_path().ok_or(PierError::NoDefaultConfig)
}

fn find_default_config_path() -> Option<PathBuf> {
    default_config_candidates()
        .into_iter()
        .find(|path| path.exists())
}

fn preferred_new_config_path() -> Option<PathBuf> {
    if let Ok(xdg_config_home) = env::var("XDG_CONFIG_HOME") {
        return Some(PathBuf::from(xdg_config_home).join("pier").join("config.toml"));
    }

    env::var("HOME")
        .ok()
        .map(|home| PathBuf::from(home).join(".pier.toml"))
}

fn default_config_candidates() -> Vec<PathBuf> {
    let mut candidates = Vec::new();

    if let Ok(current_dir) = env::current_dir() {
        candidates.push(current_dir.join("pier.toml"));
    }

    if let Ok(xdg_config_home) = env::var("XDG_CONFIG_HOME") {
        let xdg = PathBuf::from(xdg_config_home);
        candidates.push(xdg.join("pier").join("config.toml"));
        candidates.push(xdg.join("pier").join("config"));
        candidates.push(xdg.join("pier.toml"));
    }

    if let Ok(home) = env::var("HOME") {
        let home = PathBuf::from(home);
        candidates.push(home.join(".pier.toml"));
        candidates.push(home.join(".pier"));
    }

    candidates
}

fn load_config(path: &Path) -> Result<Config, PierError> {
    let raw = fs::read_to_string(path).map_err(|err| PierError::ReadConfig(path.to_path_buf(), err))?;
    parse_config(path, &raw)
}

fn parse_config(path: &Path, raw: &str) -> Result<Config, PierError> {
    let value = raw
        .parse::<Value>()
        .map_err(|err| PierError::ParseConfig(path.to_path_buf(), err.to_string()))?;

    let mut config = Config::default();
    if let Some(script_table) = value.get("scripts").and_then(Value::as_table) {
        for (alias, script_value) in script_table {
            let Some(table) = script_value.as_table() else {
                continue;
            };

            let command = table
                .get("command")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string();
            let description = table
                .get("description")
                .and_then(Value::as_str)
                .map(str::to_string);
            let tags = table
                .get("tags")
                .and_then(Value::as_array)
                .map(|array| {
                    array
                        .iter()
                        .filter_map(Value::as_str)
                        .map(str::to_string)
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();

            config.scripts.insert(
                alias.to_string(),
                Script {
                    command,
                    description,
                    tags,
                },
            );
        }
    }

    if let Some(default_table) = value.get("default").and_then(Value::as_table) {
        config.default.list_aliases = bool_from_table(default_table, &["list_aliases", "aliases_only"]).unwrap_or(false);
        config.default.cmd_full = bool_from_table(default_table, &["cmd_full", "command_full"]).unwrap_or(false);
        config.default.cmd_width = int_from_table(default_table, &["cmd_width", "command_width", "command_display"]);
    }

    Ok(config)
}

fn bool_from_table(table: &toml::value::Table, keys: &[&str]) -> Option<bool> {
    keys.iter()
        .find_map(|key| table.get(*key).and_then(Value::as_bool))
}

fn int_from_table(table: &toml::value::Table, keys: &[&str]) -> Option<usize> {
    keys.iter().find_map(|key| {
        table
            .get(*key)
            .and_then(Value::as_integer)
            .and_then(|value| usize::try_from(value).ok())
    })
}

fn write_config(path: &Path, config: &Config) -> Result<(), PierError> {
    write_config_file(path, render_config(config))
}

fn write_config_file(path: &Path, contents: String) -> Result<(), PierError> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|err| PierError::WriteConfig(path.to_path_buf(), err))?;
    }
    fs::write(path, contents).map_err(|err| PierError::WriteConfig(path.to_path_buf(), err))
}

fn render_config(config: &Config) -> String {
    if config.scripts.is_empty() {
        return "[scripts]\n\n[default]\n".to_string();
    }

    let mut out = String::new();
    for (alias, script) in &config.scripts {
        out.push_str(&format!("[scripts.{}]\n", render_table_key(alias)));
        out.push_str(&format!("command = {}\n", render_toml_string(&script.command)));
        if let Some(description) = &script.description {
            out.push_str(&format!(
                "description = {}\n",
                render_toml_string(description)
            ));
        }
        if !script.tags.is_empty() {
            out.push_str("tags = [\n");
            for tag in &script.tags {
                out.push_str(&format!("    {},\n", render_toml_string(tag)));
            }
            out.push_str("]\n");
        }
        out.push('\n');
    }
    out.push_str("[default]\n");
    out
}

fn render_table_key(key: &str) -> String {
    if key
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '-')
    {
        key.to_string()
    } else {
        format!("\"{}\"", key.replace('\\', "\\\\").replace('"', "\\\""))
    }
}

fn render_toml_string(value: &str) -> String {
    if value.is_empty() {
        return "''".to_string();
    }

    if !value.contains('\n') && !value.contains('\'') && !has_disallowed_literal_chars(value) {
        return format!("'{}'", value);
    }

    if !value.contains("'''") && !has_disallowed_literal_chars(value) {
        let mut out = String::from("'''");
        out.push('\n');
        out.push_str(value);
        out.push_str("'''");
        return out;
    }

    format!("\"{}\"", escape_basic_toml(value))
}

fn has_disallowed_literal_chars(value: &str) -> bool {
    value.chars().any(|ch| matches!(ch, '\u{0000}'..='\u{0008}' | '\u{000A}'..='\u{001F}' | '\u{007F}'))
}

fn escape_basic_toml(value: &str) -> String {
    let mut out = String::new();
    for ch in value.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\u{08}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{0C}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            ch if ch.is_control() => out.push_str(&format!("\\u{:04X}", ch as u32)),
            _ => out.push(ch),
        }
    }
    out
}

fn default_init_config() -> String {
    "[scripts.hello-pier]\ncommand = 'echo Hello, Pier!'\ndescription = 'This is an example command.'\n\n[default]\n".to_string()
}

fn edit_with_editor(initial_contents: &str) -> Result<String, PierError> {
    let editor = env::var("EDITOR").unwrap_or_else(|_| "vi".to_string());
    let parts = split_shell_words(&editor).unwrap_or_else(|_| vec![editor.clone()]);
    let Some(program) = parts.first() else {
        return Err(PierError::Editor(editor));
    };

    let mut file = NamedTempFile::new().map_err(|_| PierError::Editor(editor.clone()))?;
    file.write_all(initial_contents.as_bytes())
        .map_err(|_| PierError::Editor(editor.clone()))?;
    file.flush().map_err(|_| PierError::Editor(editor.clone()))?;

    let status = Command::new(program)
        .args(&parts[1..])
        .arg(file.path())
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .status();

    match status {
        Ok(status) if status.success() => fs::read_to_string(file.path()).map_err(|_| PierError::Editor(editor)),
        Ok(_) | Err(_) => Err(PierError::Editor(editor)),
    }
}

fn values_to_vec(matches: &ArgMatches<'_>, key: &str) -> Vec<String> {
    matches
        .values_of(key)
        .map(|values| values.map(str::to_string).collect())
        .unwrap_or_default()
}

fn run_script(alias: &str, command: &str, args: &[String]) -> Result<i32, PierError> {
    let status = Command::new("sh")
        .arg("-c")
        .arg(command)
        .arg(alias)
        .args(args)
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .status()
        .map_err(PierError::Run)?;

    Ok(status.code().unwrap_or(1))
}

fn filtered_entries<'a>(
    config: &'a Config,
    matches: &ArgMatches<'_>,
) -> Vec<(&'a str, &'a Script)> {
    let tags = values_to_vec(matches, "tags");
    if tags.is_empty() {
        return config
            .scripts
            .iter()
            .map(|(alias, script)| (alias.as_str(), script))
            .collect();
    }

    let mut entries = Vec::new();
    for wanted_tag in tags {
        for (alias, script) in &config.scripts {
            if script.tags.iter().any(|tag| tag == &wanted_tag) {
                entries.push((alias.as_str(), script));
            }
        }
    }
    entries
}

#[derive(Copy, Clone)]
enum CommandDisplay {
    Full,
    Width(usize),
}

fn render_table(entries: &[(&str, &Script)], command_display: CommandDisplay) -> String {
    let headers = ["Alias", "Tags", "Command", "Description"];
    let mut rows = Vec::new();
    for (alias, script) in entries {
        rows.push([
            (*alias).to_string(),
            script.tags.join(","),
            displayed_command(script, command_display),
            script
                .description
                .as_deref()
                .unwrap_or("")
                .lines()
                .next()
                .unwrap_or("")
                .to_string(),
        ]);
    }

    let widths = [
        max_width(headers[0], rows.iter().map(|row| row[0].as_str())),
        max_width(headers[1], rows.iter().map(|row| row[1].as_str())),
        max_width(headers[2], rows.iter().map(|row| row[2].as_str())),
        max_width(headers[3], rows.iter().map(|row| row[3].as_str())),
    ];

    let header_row = format_row(&headers, &widths);
    let separator = "≖".repeat(UnicodeWidthStr::width(header_row.as_str()));

    let mut out = String::new();
    out.push_str(&separator);
    out.push('\n');
    out.push_str(&header_row);
    out.push('\n');
    out.push_str(&separator);
    out.push('\n');
    for row in &rows {
        out.push_str(&format_row(
            &[row[0].as_str(), row[1].as_str(), row[2].as_str(), row[3].as_str()],
            &widths,
        ));
        out.push('\n');
    }
    out.push_str(&separator);
    out.push('\n');
    out
}

fn max_width<'a>(header: &str, values: impl Iterator<Item = &'a str>) -> usize {
    values.fold(UnicodeWidthStr::width(header), |width, value| {
        width.max(UnicodeWidthStr::width(value))
    })
}

fn format_row(columns: &[&str], widths: &[usize; 4]) -> String {
    let mut out = String::from("⋮");
    for (index, column) in columns.iter().enumerate() {
        out.push(' ');
        out.push_str(column);
        let padding = widths[index].saturating_sub(UnicodeWidthStr::width(*column));
        out.push_str(&" ".repeat(padding));
        out.push(' ');
        out.push('⋮');
    }
    out
}

fn displayed_command(script: &Script, command_display: CommandDisplay) -> String {
    let first_line = script.command.lines().next().unwrap_or("");
    match command_display {
        CommandDisplay::Full => first_line.to_string(),
        CommandDisplay::Width(width) => first_line.chars().take(width).collect(),
    }
}

