    "rename": "move",
    "remove": "remove",
    "rm": "remove",
    "run": "run",
    "show": "show",
}

SUGGESTION_NAMES = [
    "add",
    "config-init",
    "init",
    "copy",
    "cp",
    "edit",
    "help",
    "list",
    "ls",
    "move",
    "mv",
    "rename",
    "remove",
    "rm",
    "run",
    "show",
]


@dataclass
class DefaultOptions:
    list_aliases: bool = False
    cmd_full: bool = False
    cmd_width: int | None = None


@dataclass
class Script:
    command: str
    description: str | None = None
    tags: list[str] = field(default_factory=list)


@dataclass
class Config:
    scripts: dict[str, Script] = field(default_factory=dict)
    default: DefaultOptions = field(default_factory=DefaultOptions)


@dataclass
class GlobalOptions:
    config_file: str | None = None
    verbose: int = 0


class AppError(Exception):
    pass


class ParseExit(Exception):
    def __init__(self, message: str, code: int, to_stderr: bool) -> None:
        super().__init__(message)
        self.message = message
        self.code = code
        self.to_stderr = to_stderr


def main(argv: list[str]) -> int:
    bin_name = os.path.basename(sys.argv[0]) or "executable"
    try:
        return dispatch(argv, bin_name)
    except ParseExit as exc:
        stream = sys.stderr if exc.to_stderr else sys.stdout
        stream.write(exc.message)
        return exc.code
    except AppError as exc:
        sys.stderr.write(f"error: {exc}\n")
        return 1


def dispatch(argv: list[str], bin_name: str) -> int:
    globals_, remainder, forced_alias_mode = parse_global_args(argv, bin_name)

    if not remainder:
        raise ParseExit(required_argument_error("<alias>", top_usage(bin_name)), 1, True)

    head = remainder[0]

    if head == "help" and not forced_alias_mode:
        return dispatch_help(remainder[1:], bin_name)

    if not forced_alias_mode and head in SUBCOMMANDS:
        return dispatch_subcommand(SUBCOMMANDS[head], remainder[1:], globals_, bin_name)

    if "-" in head:
        raise ParseExit(unknown_subcommand_error(head, bin_name), 1, True)

    alias, args = parse_alias_invocation(remainder, bin_name, globals_)
    config = load_config_for_command(globals_)
    script = script_for_existing_config(config, alias)
    return run_script(alias, script.command, args)


def parse_global_args(argv: list[str], bin_name: str) -> tuple[GlobalOptions, list[str], bool]:
    globals_ = GlobalOptions(config_file=os.environ.get("PIER_CONFIG_PATH"))
    i = 0
    forced_alias_mode = False

    while i < len(argv):
        token = argv[i]
        if token == "--":
            forced_alias_mode = True
            return globals_, argv[i + 1 :], True
        if token in ("-h", "--help"):
            raise ParseExit(top_help_long(bin_name), 0, False)
        if token in ("-V", "--version"):
            raise ParseExit(f"{APP_NAME} {VERSION}\n", 0, False)
        if token in ("-v", "--verbose"):
            globals_.verbose += 1
            i += 1
            continue
        if token in ("-c", "--config-file"):
            if i + 1 >= len(argv):
                raise ParseExit(missing_option_value_error(token, top_usage(bin_name)), 1, True)
            globals_.config_file = argv[i + 1]
            i += 2
            continue
        if token.startswith("-"):
            raise ParseExit(unexpected_argument_error(token, top_usage(bin_name)), 1, True)
        return globals_, argv[i:], False

    return globals_, [], forced_alias_mode


def dispatch_help(args: list[str], bin_name: str) -> int:
    if not args:
        sys.stdout.write(top_help_short(bin_name))
        return 0

    topic = SUBCOMMANDS.get(args[0], args[0])
    if topic == "add":
        sys.stdout.write(add_help(bin_name))
        return 0
    if topic == "config-init":
        sys.stdout.write(config_init_help(bin_name))
        return 0
    if topic == "copy":
        sys.stdout.write(copy_help(bin_name))
        return 0
    if topic == "edit":
        sys.stdout.write(edit_help(bin_name))
        return 0
    if topic == "list":
        sys.stdout.write(list_help(bin_name))
        return 0
    if topic == "move":
        sys.stdout.write(move_help(bin_name))
        return 0
    if topic == "remove":
        sys.stdout.write(remove_help(bin_name))
        return 0
    if topic == "run":
        sys.stdout.write(run_help(bin_name))
        return 0
    if topic == "show":
        sys.stdout.write(show_help(bin_name))
        return 0

    sys.stdout.write(top_help_short(bin_name))
    return 0


def dispatch_subcommand(name: str, args: list[str], globals_: GlobalOptions, bin_name: str) -> int:
    if name == "add":
        parsed = parse_add_args(args, bin_name)
        config_path = resolve_existing_config_path(globals_)
        config = load_config(config_path)
        if parsed["alias"] in config.scripts and not parsed["force"]:
            raise AppError(alias_already_exists_error(parsed["alias"]))
        if parsed["command"] is None:
            command = edit_with_editor("")
        else:
            command = parsed["command"]
        config.scripts[parsed["alias"]] = Script(
            command=command,
            description=parsed["description"],
            tags=parsed["tags"],
        )
        write_config(config_path, config)
        sys.stdout.write(f"Added {parsed['alias']}\n")
        return 0

    if name == "config-init":
        parsed = parse_config_init_args(args, bin_name)
        if parsed["show_help"]:
            sys.stdout.write(config_init_help(bin_name))
            return 0
        if parsed["show_version"]:
            sys.stdout.write(f"{bin_name}-config-init {VERSION}\n")
            return 0
        config_path = resolve_init_config_path(globals_)
        if os.path.exists(config_path):
            raise AppError(f"Cannot initialize config at {config_path}, file already exists.")
        write_file(config_path, default_init_config())
        sys.stdout.write("Added hello-pier\n")
        return 0

    if name == "copy":
        parsed = parse_copy_args(args, bin_name)
        config = load_config_for_command(globals_)
        ensure_scripts_exist(config)
        source = script_for_existing_config(config, parsed["from_alias"])
        if parsed["to_alias"] in config.scripts:
            raise AppError(alias_already_exists_error(parsed["to_alias"]))
        config.scripts[parsed["to_alias"]] = Script(
            command=source.command,
            description=source.description,
            tags=list(source.tags),
        )
        write_config(resolve_existing_config_path(globals_), config)
        sys.stdout.write(
            f"Copy from alias {parsed['from_alias']} to new alias {parsed['to_alias']}\n"
        )
        return 0

    if name == "edit":
        parsed = parse_single_alias_args(args, bin_name, "edit")
        config = load_config_for_command(globals_)
        ensure_scripts_exist(config)
        script = script_for_existing_config(config, parsed["alias"])
        script.command = edit_with_editor(script.command)
        write_config(resolve_existing_config_path(globals_), config)
        sys.stdout.write(f"Edited {parsed['alias']}\n")
        return 0

    if name == "list":
        parsed = parse_list_args(args, bin_name)
        config = load_config_for_command(globals_)
        ensure_scripts_exist(config)
        entries = filter_entries(config, parsed["tags"])
        list_aliases = parsed["list_aliases"]
        if not list_aliases and not parsed["cmd_full"] and parsed["cmd_width"] is None:
            list_aliases = config.default.list_aliases
        if list_aliases:
            for alias, _ in entries:
                sys.stdout.write(f"{alias}\n")
            return 0
        if parsed["cmd_full"]:
            display = ("full", None)
        elif parsed["cmd_width"] is not None:
            display = ("width", parsed["cmd_width"])
        elif config.default.cmd_full:
            display = ("full", None)
        elif config.default.cmd_width is not None:
            display = ("width", config.default.cmd_width)
        else:
            display = ("full", None)
        sys.stdout.write(render_table(entries, display))
        return 0

    if name == "move":
        parsed = parse_move_args(args, bin_name)
        config = load_config_for_command(globals_)
        ensure_scripts_exist(config)
        source = script_for_existing_config(config, parsed["from_alias"])
        destination_exists = parsed["to_alias"] in config.scripts
        if destination_exists and not parsed["force"]:
            raise AppError(alias_already_exists_error(parsed["to_alias"]))
        config.scripts.pop(parsed["from_alias"], None)
        config.scripts[parsed["to_alias"]] = Script(
            command=source.command,
            description=source.description,
            tags=list(source.tags),
        )
        write_config(resolve_existing_config_path(globals_), config)
        sys.stdout.write(
            f"Move from alias {parsed['from_alias']} to new alias {parsed['to_alias']}\n"
        )
        return 0

    if name == "remove":
        parsed = parse_single_alias_args(args, bin_name, "remove")
        config = load_config_for_command(globals_)
        ensure_scripts_exist(config)
        if parsed["alias"] not in config.scripts:
            raise AppError(alias_not_found_error(parsed["alias"]))
        config.scripts.pop(parsed["alias"], None)
        write_config(resolve_existing_config_path(globals_), config)
        sys.stdout.write(f"Removed {parsed['alias']}\n")
        return 0

    if name == "run":
        parsed = parse_run_args(args, bin_name)
        config = load_config_for_command(globals_)
        script = script_for_existing_config(config, parsed["alias"])
        return run_script(parsed["alias"], script.command, parsed["args"])

    if name == "show":
        parsed = parse_single_alias_args(args, bin_name, "show")
        config = load_config_for_command(globals_)
        script = script_for_existing_config(config, parsed["alias"])
        sys.stdout.write(script.command)
        sys.stdout.write("\n")
        return 0

    raise AppError(f"Unsupported command: {name}")


def parse_alias_invocation(
    args: list[str], bin_name: str, globals_: GlobalOptions
) -> tuple[str, list[str]]:
    alias = args[0]
    if any(token.startswith("-") for token in args[1:]):
        usage = direct_alias_usage(bin_name, globals_)
        token = next(token for token in args[1:] if token.startswith("-"))
        raise ParseExit(unexpected_argument_error(token, usage), 1, True)
    return alias, args[1:]


def parse_add_args(args: list[str], bin_name: str) -> dict[str, object]:
    alias: str | None = None
    description: str | None = None
    tags: list[str] = []
    force = False
    command: str | None = None
    i = 0

    while i < len(args):
        token = args[i]
        if token in ("-h", "--help"):
            raise ParseExit(add_help(bin_name), 0, False)
        if token in ("-V", "--version"):
            raise ParseExit(f"{bin_name}-add {VERSION}\n", 0, False)
        if token == "--":
            if i + 1 < len(args):
                command = args[i + 1]
            break
        if token in ("-f", "--force"):
            force = True
            i += 1
            continue
        if token in ("-a", "--alias"):
            if i + 1 >= len(args):
                raise ParseExit(missing_option_value_error(token, add_usage(bin_name)), 1, True)
            alias = args[i + 1]
            i += 2
            continue
        if token in ("-d", "--description"):
            if i + 1 >= len(args):
                raise ParseExit(missing_option_value_error(token, add_usage(bin_name)), 1, True)
            description = args[i + 1]
            i += 2
            continue
        if token in ("-t", "--tag"):
            if i + 1 >= len(args):
                raise ParseExit(missing_option_value_error(token, add_usage(bin_name)), 1, True)
            tags.append(args[i + 1])
            i += 2
            continue
        if token.startswith("-"):
            raise ParseExit(unexpected_argument_error(token, add_usage(bin_name)), 1, True)
        i += 1

    if alias is None:
        raise ParseExit(required_argument_error("--alias <alias>", add_usage(bin_name)), 1, True)

    return {
        "alias": alias,
        "description": description,
        "tags": tags,
        "force": force,
        "command": command,
    }


def parse_config_init_args(args: list[str], bin_name: str) -> dict[str, bool]:
    show_help = False
    show_version = False
    for token in args:
        if token in ("-h", "--help"):
            show_help = True
        elif token in ("-V", "--version"):
            show_version = True
        elif token.startswith("-"):
            raise ParseExit(unexpected_argument_error(token, config_init_usage(bin_name)), 1, True)
        else:
            raise ParseExit(unexpected_argument_error(token, config_init_usage(bin_name)), 1, True)
    return {"show_help": show_help, "show_version": show_version}


def parse_copy_args(args: list[str], bin_name: str) -> dict[str, str]:
    for token in args:
        if token in ("-h", "--help"):
            raise ParseExit(copy_help(bin_name), 0, False)
        if token in ("-V", "--version"):
            raise ParseExit(f"{bin_name}-copy {VERSION}\n", 0, False)

    positionals = [token for token in args if not token.startswith("-")]
    unknown_flags = [token for token in args if token.startswith("-") and token not in ("-h", "--help", "-V", "--version")]
    if unknown_flags:
        raise ParseExit(unexpected_argument_error(unknown_flags[0], copy_usage(bin_name)), 1, True)
    if len(positionals) < 2:
        missing = "<from-alias>" if len(positionals) == 0 else "<to-alias>"
        raise ParseExit(required_argument_error(missing, copy_usage(bin_name)), 1, True)
    return {"from_alias": positionals[0], "to_alias": positionals[1]}


def parse_move_args(args: list[str], bin_name: str) -> dict[str, object]:
    force = False
    positionals: list[str] = []
    i = 0
    while i < len(args):
        token = args[i]
        if token in ("-h", "--help"):
            raise ParseExit(move_help(bin_name), 0, False)
        if token in ("-V", "--version"):
            raise ParseExit(f"{bin_name}-move {VERSION}\n", 0, False)
        if token in ("-f", "--force"):
            force = True
            i += 1
            continue
        if token.startswith("-"):
            raise ParseExit(unexpected_argument_error(token, move_usage(bin_name)), 1, True)
        positionals.append(token)
        i += 1

    if len(positionals) < 2:
        missing = "<from-alias>" if len(positionals) == 0 else "<to-alias>"
        raise ParseExit(required_argument_error(missing, move_usage(bin_name)), 1, True)
    return {"from_alias": positionals[0], "to_alias": positionals[1], "force": force}


def parse_list_args(args: list[str], bin_name: str) -> dict[str, object]:
    parsed = {"cmd_full": False, "list_aliases": False, "cmd_width": None, "tags": []}
    i = 0
    while i < len(args):
        token = args[i]
        if token in ("-h", "--help"):
            raise ParseExit(list_help(bin_name), 0, False)
        if token in ("-V", "--version"):
            raise ParseExit(f"{bin_name}-list {VERSION}\n", 0, False)
        if token in ("-l", "--cmd_full"):
            parsed["cmd_full"] = True
            i += 1
            continue
        if token in ("-q", "--list_aliases"):
            parsed["list_aliases"] = True
            i += 1
            continue
        if token in ("-c", "--cmd_width"):
            if i + 1 >= len(args):
                raise ParseExit(missing_option_value_error(token, list_usage(bin_name)), 1, True)
            try:
                parsed["cmd_width"] = int(args[i + 1])
            except ValueError:
                parsed["cmd_width"] = 0
            i += 2
            continue
        if token in ("-t", "--tag"):
            if i + 1 >= len(args):
                raise ParseExit(missing_option_value_error(token, list_usage(bin_name)), 1, True)
            parsed["tags"].append(args[i + 1])
            i += 2
            continue
        raise ParseExit(unexpected_argument_error(token, list_usage(bin_name)), 1, True)
    return parsed


def parse_run_args(args: list[str], bin_name: str) -> dict[str, object]:
    alias: str | None = None
    forwarded: list[str] = []
    after_double_dash = False
    i = 0
    while i < len(args):
        token = args[i]
        if token in ("-h", "--help") and alias is None and not after_double_dash:
            raise ParseExit(run_help(bin_name), 0, False)
        if token in ("-V", "--version") and alias is None and not after_double_dash:
            raise ParseExit(f"{bin_name}-run {VERSION}\n", 0, False)
        if token == "--" and not after_double_dash:
            after_double_dash = True
            i += 1
            continue
        if alias is None:
            if token.startswith("-"):
                raise ParseExit(required_argument_error("<alias>", run_usage(bin_name)), 1, True)
            alias = token
            i += 1
            continue
        if token.startswith("-") and not after_double_dash:
            raise ParseExit(unexpected_argument_error(token, run_usage(bin_name)), 1, True)
        forwarded.append(token)
        i += 1

    if alias is None:
        raise ParseExit(required_argument_error("<alias>", run_usage(bin_name)), 1, True)

    return {"alias": alias, "args": forwarded}


def parse_single_alias_args(args: list[str], bin_name: str, command: str) -> dict[str, str]:
    help_text = {
        "edit": edit_help,
        "remove": remove_help,
        "show": show_help,
    }[command]
    usage_text = {
        "edit": edit_usage,
        "remove": remove_usage,
        "show": show_usage,
    }[command]
    for token in args:
        if token in ("-h", "--help"):
            raise ParseExit(help_text(bin_name), 0, False)
        if token in ("-V", "--version"):
            raise ParseExit(f"{bin_name}-{command} {VERSION}\n", 0, False)
    positionals = [token for token in args if not token.startswith("-")]
    unknown_flags = [token for token in args if token.startswith("-") and token not in ("-h", "--help", "-V", "--version")]
    if unknown_flags:
        raise ParseExit(unexpected_argument_error(unknown_flags[0], usage_text(bin_name)), 1, True)
    if not positionals:
        raise ParseExit(required_argument_error("<alias>", usage_text(bin_name)), 1, True)
    return {"alias": positionals[0]}


def direct_alias_usage(bin_name: str, globals_: GlobalOptions) -> str:
    if globals_.config_file is not None:
        return f"{bin_name} <alias> --config-file <path>"
    return top_usage(bin_name)


def load_config_for_command(globals_: GlobalOptions) -> Config:
    path = resolve_existing_config_path(globals_)
    return load_config(path)


def resolve_existing_config_path(globals_: GlobalOptions) -> str:
    if globals_.config_file is not None:
        return globals_.config_file
    found = find_default_config_path()
    if found is None:
        raise AppError("No default config file found. See help for more info.")
    return found


def resolve_init_config_path(globals_: GlobalOptions) -> str:
    if globals_.config_file is not None:
        return globals_.config_file
    found = find_default_config_path()
    if found is not None:
        return found
    preferred = preferred_new_config_path()
    if preferred is None:
        raise AppError("No default config file found. See help for more info.")
    return preferred


def find_default_config_path() -> str | None:
    for candidate in default_config_candidates():
        if os.path.exists(candidate):
            return candidate
    return None


def default_config_candidates() -> list[str]:
    candidates: list[str] = []
    candidates.append(os.path.join(os.getcwd(), "pier.toml"))
    xdg_config_home = os.environ.get("XDG_CONFIG_HOME")
    if xdg_config_home:
        candidates.append(os.path.join(xdg_config_home, "pier", "config.toml"))
        candidates.append(os.path.join(xdg_config_home, "pier", "config"))
        candidates.append(os.path.join(xdg_config_home, "pier.toml"))
    home = os.environ.get("HOME")
    if home:
        candidates.append(os.path.join(home, ".pier.toml"))
        candidates.append(os.path.join(home, ".pier"))
    return candidates


def preferred_new_config_path() -> str | None:
    xdg_config_home = os.environ.get("XDG_CONFIG_HOME")
    if xdg_config_home:
        return os.path.join(xdg_config_home, "pier", "config.toml")
    home = os.environ.get("HOME")
    if home:
        return os.path.join(home, ".pier.toml")
    return None


def load_config(path: str) -> Config:
    try:
        with open(path, "rb") as handle:
            data = tomli.load(handle)
    except OSError as exc:
        message = f"Unable to read config from file {path}: {os.strerror(exc.errno or 1)} (os error {exc.errno or 1}) "
        raise AppError(message) from exc
    except tomli.TOMLDecodeError as exc:
        raise AppError(f"Unable to parse config from file {path}: {exc}") from exc

    default_section = data.get("default")
    if not isinstance(default_section, dict):
        default_section = {}
    scripts_section = data.get("scripts")
    if not isinstance(scripts_section, dict):
        scripts_section = {}

    config = Config()
    config.default.list_aliases = bool(default_section.get("list_aliases", default_section.get("aliases_only", False)))
    config.default.cmd_full = bool(default_section.get("cmd_full", default_section.get("command_full", False)))
    width_value = default_section.get("cmd_width", default_section.get("command_width", default_section.get("command_display")))
    if isinstance(width_value, int):
        config.default.cmd_width = width_value

    for alias, raw_script in scripts_section.items():
        if not isinstance(alias, str) or not isinstance(raw_script, dict):
            continue
        command = raw_script.get("command", "")
        description = raw_script.get("description")
        tags = raw_script.get("tags", [])
        if not isinstance(command, str):
            command = ""
        if description is not None and not isinstance(description, str):
            description = None
        if not isinstance(tags, list):
            tags = []
        config.scripts[alias] = Script(
            command=command,
            description=description,
            tags=[tag for tag in tags if isinstance(tag, str)],
        )

    return config


def script_for_existing_config(config: Config, alias: str) -> Script:
    ensure_scripts_exist(config)
    script = config.scripts.get(alias)
    if script is None:
        raise AppError(alias_not_found_error(alias))
    return script


def ensure_scripts_exist(config: Config) -> None:
    if not config.scripts:
        raise AppError("No scripts exist. Would you like to add a new script?")


def write_config(path: str, config: Config) -> None:
    write_file(path, render_config(config))


def write_file(path: str, contents: str) -> None:
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="") as handle:
        handle.write(contents)


def render_config(config: Config) -> str:
    if not config.scripts:
        return "[scripts]\n\n[default]\n"

    chunks: list[str] = []
    for alias in sorted(config.scripts):
        script = config.scripts[alias]
        chunks.append(f"[scripts.{render_table_key(alias)}]\n")
        chunks.append(f"command = {render_toml_string(script.command)}\n")
        if script.description is not None:
            chunks.append(f"description = {render_toml_string(script.description)}\n")
        if script.tags:
            chunks.append("tags = [\n")
            for tag in script.tags:
                chunks.append(f"    {render_toml_string(tag)},\n")
            chunks.append("]\n")
        chunks.append("\n")
    chunks.append("[default]\n")
    return "".join(chunks)


def render_table_key(key: str) -> str:
    if key and all(ch.isalnum() or ch in "_-" for ch in key):
        return key
    escaped = key.replace("\\", "\\\\").replace('"', '\\"')
    return f'"{escaped}"'


def render_toml_string(value: str) -> str:
    if value == "":
        return "''"
    if "\n" not in value and "'" not in value and not has_disallowed_literal_chars(value):
        return f"'{value}'"
    if "'''" not in value and not has_disallowed_literal_chars(value, allow_newlines=True):
        return "'''\n" + value + "'''"
    return '"' + escape_basic_toml(value) + '"'


def has_disallowed_literal_chars(value: str, allow_newlines: bool = False) -> bool:
    for ch in value:
        if ch == "\n" and allow_newlines:
            continue
        code = ord(ch)
        if code == 0x09:
            continue
        if code < 0x20 or code == 0x7F:
            return True
    return False


def escape_basic_toml(value: str) -> str:
    escaped: list[str] = []
    for ch in value:
        if ch == "\\":
            escaped.append("\\\\")
        elif ch == '"':
            escaped.append('\\"')
        elif ch == "\b":
            escaped.append("\\b")
        elif ch == "\t":
            escaped.append("\\t")
        elif ch == "\n":
            escaped.append("\\n")
        elif ch == "\f":
            escaped.append("\\f")
        elif ch == "\r":
            escaped.append("\\r")
        elif ord(ch) < 0x20 or ord(ch) == 0x7F:
            escaped.append(f"\\u{ord(ch):04X}")
        else:
            escaped.append(ch)
    return "".join(escaped)


