        "[default]\n"
    )


def edit_with_editor(initial_contents: str) -> str:
    editor = os.environ.get("EDITOR", "vi")
    try:
        parts = shlex.split(editor)
    except ValueError as exc:
        raise AppError(editor_error(editor)) from exc
    if not parts:
        raise AppError(editor_error(editor))

    fd, path = tempfile.mkstemp(prefix="pier-")
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            handle.write(initial_contents)
        try:
            result = subprocess.run(parts + [path], check=False)
        except OSError as exc:
            raise AppError(editor_error(editor)) from exc
        if result.returncode != 0:
            raise AppError(editor_error(editor))
        with open(path, "r", encoding="utf-8") as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except OSError:
            pass


def run_script(alias: str, command: str, args: list[str]) -> int:
    try:
        result = subprocess.run(["sh", "-c", command, alias, *args], check=False)
    except OSError as exc:
        raise AppError(f"Failed to run script: {exc}") from exc
    return result.returncode


def filter_entries(config: Config, tags: list[str]) -> list[tuple[str, Script]]:
    if not tags:
        return [(alias, config.scripts[alias]) for alias in sorted(config.scripts)]

    entries: list[tuple[str, Script]] = []
    for wanted_tag in tags:
        for alias in sorted(config.scripts):
            script = config.scripts[alias]
            if wanted_tag in script.tags:
                entries.append((alias, script))
    return entries


def render_table(entries: list[tuple[str, Script]], display: tuple[str, int | None]) -> str:
    rows: list[list[str]] = []
    for alias, script in entries:
        rows.append(
            [
                alias,
                ",".join(script.tags),
                display_command(script.command, display),
                first_line(script.description or ""),
            ]
        )

    headers = ["Alias", "Tags", "Command", "Description"]
    widths = [
        max([len(headers[0]), *[len(row[0]) for row in rows]]),
        max([len(headers[1]), *[len(row[1]) for row in rows]]),
        max([len(headers[2]), *[len(row[2]) for row in rows]]),
        max([len(headers[3]), *[len(row[3]) for row in rows]]),
    ]

    header_row = format_row(headers, widths)
    separator = "≖" * len(header_row)
    lines = [separator, header_row, separator]
    lines.extend(format_row(row, widths) for row in rows)
    lines.append(separator)
    return "\n".join(lines) + "\n"


def format_row(columns: Iterable[str], widths: list[int]) -> str:
    parts = ["⋮"]
    for index, column in enumerate(columns):
        parts.append(" ")
        parts.append(column)
        parts.append(" " * max(0, widths[index] - len(column)))
        parts.append(" ⋮")
    return "".join(parts)


def display_command(command: str, display: tuple[str, int | None]) -> str:
    first = first_line(command)
    if display[0] == "width" and display[1] is not None:
        return first[: display[1]]
    return first


